'use client';

import * as DropdownMenuPrimitive from '@radix-ui/react-dropdown-menu';
import * as React from 'react';

import { Icon } from '@/components/ui/icon';
import { cn } from '@/lib/utils';

function DropdownMenu({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Root>) {
  return <DropdownMenuPrimitive.Root data-slot="dropdown-menu" {...props} />;
}

function DropdownMenuPortal({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Portal>) {
  return (
    <DropdownMenuPrimitive.Portal data-slot="dropdown-menu-portal" {...props} />
  );
}

function DropdownMenuTrigger({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Trigger>) {
  return (
    <DropdownMenuPrimitive.Trigger
      data-slot="dropdown-menu-trigger"
      {...props}
    />
  );
}

interface DropdownMenuContentProps extends React.ComponentProps<
  typeof DropdownMenuPrimitive.Content
> {
  children?: React.ReactNode;
  onOpenAutoFocus?: (event: Event) => void;
}

function DropdownMenuContent({
  className,
  sideOffset = 4,
  ...props
}: DropdownMenuContentProps) {
  return (
    <DropdownMenuPrimitive.Portal>
      <DropdownMenuPrimitive.Content
        data-slot="dropdown-menu-content"
        sideOffset={sideOffset}
        className={cn(
          'bg-stateslayer-overlay-active-inverse text-fg-primary shadow-elevation-1 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 z-50 max-h-(--radix-dropdown-menu-content-available-height) origin-(--radix-dropdown-menu-content-transform-origin) overflow-x-hidden overflow-y-auto p-1',
          className,
        )}
        {...props}
      />
    </DropdownMenuPrimitive.Portal>
  );
}

function DropdownMenuGroup({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Group>) {
  return (
    <DropdownMenuPrimitive.Group data-slot="dropdown-menu-group" {...props} />
  );
}

function DropdownMenuItem({
  className,
  inset,
  variant = 'default',
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Item> & {
  inset?: boolean;
  variant?: 'default' | 'destructive';
}) {
  return (
    <DropdownMenuPrimitive.Item
      data-slot="dropdown-menu-item"
      data-inset={inset}
      data-variant={variant}
      className={cn(
        'paragraph-regular-primary text-fg-secondary data-[highlighted]:bg-stateslayer-overlay-hover data-[highlighted]:text-fg-primary active:bg-stateslayer-overlay-pressed [&_svg:not([class*="text-"])]:text-fg-tertiary relative flex cursor-default items-center gap-2 py-2 pr-2 pl-1 outline-none select-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50 data-[inset]:pl-8 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*="size-"])]:size-4',
        'data-[variant=destructive]:text-destructive data-[variant=destructive]:data-[highlighted]:bg-destructive/10 data-[variant=destructive]:data-[highlighted]:text-destructive dark:data-[variant=destructive]:data-[highlighted]:bg-destructive/20 data-[variant=destructive]:[&_svg:not([class*="text-"])]:!text-destructive',
        className,
      )}
      {...props}
    />
  );
}

function DropdownMenuCheckboxItem({
  className,
  children,
  checked,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.CheckboxItem>) {
  return (
    <DropdownMenuPrimitive.CheckboxItem
      data-slot="dropdown-menu-checkbox-item"
      className={cn(
        'paragraph-regular-primary text-fg-secondary data-[highlighted]:bg-stateslayer-overlay-hover data-[highlighted]:text-fg-primary active:bg-stateslayer-overlay-pressed relative flex cursor-default items-center gap-2 py-2 pr-2 pl-8 outline-none select-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*="size-"])]:size-4',
        className,
      )}
      checked={checked}
      {...props}>
      <span className="pointer-events-none absolute left-2 flex size-3.5 items-center justify-center">
        <DropdownMenuPrimitive.ItemIndicator>
          <Icon icon="check" className="size-4" />
        </DropdownMenuPrimitive.ItemIndicator>
      </span>
      {children}
    </DropdownMenuPrimitive.CheckboxItem>
  );
}

function DropdownMenuRadioGroup({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.RadioGroup>) {
  return (
    <DropdownMenuPrimitive.RadioGroup
      data-slot="dropdown-menu-radio-group"
      {...props}
    />
  );
}

function DropdownMenuRadioItem({
  className,
  children,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.RadioItem>) {
  return (
    <DropdownMenuPrimitive.RadioItem
      data-slot="dropdown-menu-radio-item"
      className={cn(
        'paragraph-regular-primary text-fg-secondary data-[highlighted]:bg-stateslayer-overlay-hover data-[highlighted]:text-fg-primary active:bg-stateslayer-overlay-pressed relative flex cursor-default items-center gap-2 py-2 pr-2 pl-8 outline-none select-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*="size-"])]:size-4',
        className,
      )}
      {...props}>
      <span className="pointer-events-none absolute left-2 flex size-3.5 items-center justify-center">
        <DropdownMenuPrimitive.ItemIndicator>
          <Icon
            icon="circle"
            style={{
              fontSize: 8,
              width: 8,
              height: 8,
              lineHeight: '8px',
              fontVariationSettings: "'FILL' 1, 'wght' 400, 'opsz' 20",
            }}
          />
        </DropdownMenuPrimitive.ItemIndicator>
      </span>
      {children}
    </DropdownMenuPrimitive.RadioItem>
  );
}

function DropdownMenuLabel({
  className,
  inset,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Label> & {
  inset?: boolean;
}) {
  return (
    <DropdownMenuPrimitive.Label
      data-slot="dropdown-menu-label"
      data-inset={inset}
      className={cn(
        'text-fg-tertiary paragraph-small-primary px-2 py-1.5 data-[inset]:pl-8',
        className,
      )}
      {...props}
    />
  );
}

function DropdownMenuSeparator({
  className,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Separator>) {
  return (
    <div
      className={cn(
        'pointer-events-none -mx-1 my-1 flex h-2 w-full shrink-0 flex-col',
        className,
      )}>
      <DropdownMenuPrimitive.Separator
        className="border-stroke-divider h-1 w-full shrink-0 border-0 border-b border-solid bg-transparent"
        data-slot="dropdown-menu-separator"
        {...props}
      />
      <div aria-hidden className="h-1 w-full shrink-0" />
    </div>
  );
}

function DropdownMenuShortcut({
  className,
  ...props
}: React.ComponentProps<'span'>) {
  return (
    <span
      data-slot="dropdown-menu-shortcut"
      className={cn(
        'text-fg-tertiary ml-auto text-xs tracking-widest',
        className,
      )}
      {...props}
    />
  );
}

function DropdownMenuSub({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Sub>) {
  return <DropdownMenuPrimitive.Sub data-slot="dropdown-menu-sub" {...props} />;
}

function DropdownMenuSubTrigger({
  className,
  inset,
  children,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.SubTrigger> & {
  inset?: boolean;
}) {
  return (
    <DropdownMenuPrimitive.SubTrigger
      data-slot="dropdown-menu-sub-trigger"
      data-inset={inset}
      className={cn(
        'paragraph-regular-primary text-fg-secondary data-[highlighted]:bg-stateslayer-overlay-hover data-[highlighted]:text-fg-primary data-[state=open]:bg-stateslayer-overlay-hover data-[state=open]:text-fg-primary [&_svg:not([class*="text-"])]:text-fg-tertiary flex cursor-default items-center gap-2 py-2 pr-2 pl-1 outline-none select-none data-[inset]:pl-8 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*="size-"])]:size-4',
        className,
      )}
      {...props}>
      {children}
      <Icon icon="chevron_right" className="ml-auto size-4" />
    </DropdownMenuPrimitive.SubTrigger>
  );
}

type DropdownMenuSubContentProps = React.ComponentProps<
  typeof DropdownMenuPrimitive.SubContent
> & {
  children?: React.ReactNode;
};

function DropdownMenuSubContent({
  className,
  ...props
}: DropdownMenuSubContentProps) {
  return (
    <DropdownMenuPrimitive.SubContent
      data-slot="dropdown-menu-sub-content"
      className={cn(
        'bg-stateslayer-overlay-active-inverse text-fg-primary shadow-elevation-1 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 z-50 origin-(--radix-dropdown-menu-content-transform-origin) overflow-hidden p-1',
        className,
      )}
      {...props}
    />
  );
}

export {
  DropdownMenu,
  DropdownMenuPortal,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuItem,
  DropdownMenuCheckboxItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubTrigger,
  DropdownMenuSubContent,
};

import * as React from 'react';

import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuPortal,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Icon } from '@/components/ui/icon';
import { Toggle } from '@/components/ui/toggle';

// When the menu trigger merges props, Radix may set `data-state="open"` instead of
// the toggle’s `on` — mirror the pressed styles for both.
const DROPDOWN_TOGGLE_TRIGGER_OPEN =
  'data-[state=open]:bg-fill-active data-[state=open]:text-fg-primary-inverse data-[state=open]:border-stroke-active-inverse data-[state=open]:border-2';

/** Pass on `DropdownMenuContent` / `DropdownMenuSubContent` via `className`. */
const DROPDOWN_MENU_PANEL_CLASS = 'w-[256px] max-w-[256px] min-w-[256px]';

function DropdownMenuWithToggleTrigger({
  triggerLabel,
  children,
}: Readonly<{
  triggerLabel: React.ReactNode;
  children: React.ReactNode;
}>) {
  const [open, setOpen] = React.useState(false);

  return (
    <DropdownMenu open={open} onOpenChange={setOpen}>
      <DropdownMenuTrigger asChild>
        <Toggle
          variant="outline"
          pressed={open}
          onPressedChange={setOpen}
          className={DROPDOWN_TOGGLE_TRIGGER_OPEN}>
          {triggerLabel}
        </Toggle>
      </DropdownMenuTrigger>

      {children}
    </DropdownMenu>
  );
}

// ============================================================================
// Example Components
// ============================================================================

/**
 * Basic dropdown menu with labels and separators
 */
export function DropdownMenuDemo() {
  return (
    <DropdownMenuWithToggleTrigger triggerLabel="Open">
      <DropdownMenuContent align="start" className={DROPDOWN_MENU_PANEL_CLASS}>
        <DropdownMenuGroup>
          <DropdownMenuLabel>My Account</DropdownMenuLabel>
          <DropdownMenuItem>Profile</DropdownMenuItem>
          <DropdownMenuItem>Billing</DropdownMenuItem>
          <DropdownMenuItem>Settings</DropdownMenuItem>
        </DropdownMenuGroup>

        <DropdownMenuSeparator />

        <DropdownMenuItem>GitHub</DropdownMenuItem>
        <DropdownMenuItem>Support</DropdownMenuItem>
        <DropdownMenuItem disabled>API</DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenuWithToggleTrigger>
  );
}

/**
 * Dropdown with keyboard shortcut hints
 */
export function DropdownMenuWithShortcuts() {
  return (
    <DropdownMenuWithToggleTrigger triggerLabel="Open">
      <DropdownMenuContent align="start" className={DROPDOWN_MENU_PANEL_CLASS}>
        <DropdownMenuGroup>
          <DropdownMenuLabel>My Account</DropdownMenuLabel>

          <DropdownMenuItem>
            Profile
            <DropdownMenuShortcut>⇧⌘P</DropdownMenuShortcut>
          </DropdownMenuItem>

          <DropdownMenuItem>
            Billing
            <DropdownMenuShortcut>⌘B</DropdownMenuShortcut>
          </DropdownMenuItem>

          <DropdownMenuItem>
            Settings
            <DropdownMenuShortcut>⌘S</DropdownMenuShortcut>
          </DropdownMenuItem>
        </DropdownMenuGroup>

        <DropdownMenuSeparator />

        <DropdownMenuItem>
          Log out
          <DropdownMenuShortcut>⇧⌘Q</DropdownMenuShortcut>
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenuWithToggleTrigger>
  );
}

/**
 * Dropdown with icons alongside labels
 */
export function DropdownMenuWithIcons() {
  return (
    <DropdownMenuWithToggleTrigger triggerLabel="Open">
      <DropdownMenuContent align="start" className={DROPDOWN_MENU_PANEL_CLASS}>
        <DropdownMenuItem>
          <Icon icon="person" className="size-4" />
          Profile
        </DropdownMenuItem>

        <DropdownMenuItem>
          <Icon icon="attach_money" className="size-4" />
          Billing
        </DropdownMenuItem>

        <DropdownMenuItem>
          <Icon icon="key" className="size-4" />
          Settings
        </DropdownMenuItem>

        <DropdownMenuSeparator />

        <DropdownMenuItem variant="destructive">
          <Icon icon="close" className="size-4" />
          Log out
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenuWithToggleTrigger>
  );
}

/**
 * Nested submenus for secondary actions
 */
export function DropdownMenuWithSubmenu() {
  return (
    <DropdownMenuWithToggleTrigger triggerLabel="Open">
      <DropdownMenuContent align="start" className={DROPDOWN_MENU_PANEL_CLASS}>
        <DropdownMenuGroup>
          <DropdownMenuItem>
            <Icon icon="person" className="size-4" />
            Team
          </DropdownMenuItem>

          <DropdownMenuSub>
            <DropdownMenuSubTrigger>
              <Icon icon="send" className="size-4" />
              Invite users
            </DropdownMenuSubTrigger>

            <DropdownMenuPortal>
              <DropdownMenuSubContent className={DROPDOWN_MENU_PANEL_CLASS}>
                <DropdownMenuItem>
                  <Icon icon="mail" className="size-4" />
                  Email
                </DropdownMenuItem>

                <DropdownMenuItem>Message</DropdownMenuItem>

                <DropdownMenuSeparator />

                <DropdownMenuItem>More&hellip;</DropdownMenuItem>
              </DropdownMenuSubContent>
            </DropdownMenuPortal>
          </DropdownMenuSub>

          <DropdownMenuItem>
            New Team
            <DropdownMenuShortcut>⌘+T</DropdownMenuShortcut>
          </DropdownMenuItem>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenuWithToggleTrigger>
  );
}

/**
 * Checkbox items for toggling options
 */
export function DropdownMenuWithCheckboxes() {
  const [showStatusBar, setShowStatusBar] = React.useState(true);
  const [showActivityBar, setShowActivityBar] = React.useState(false);
  const [showPanel, setShowPanel] = React.useState(false);

  return (
    <DropdownMenuWithToggleTrigger triggerLabel="Open">
      <DropdownMenuContent align="start" className={DROPDOWN_MENU_PANEL_CLASS}>
        <DropdownMenuGroup>
          <DropdownMenuLabel>Appearance</DropdownMenuLabel>

          <DropdownMenuCheckboxItem
            checked={showStatusBar}
            onCheckedChange={setShowStatusBar}>
            Status Bar
          </DropdownMenuCheckboxItem>

          <DropdownMenuCheckboxItem
            checked={showActivityBar}
            onCheckedChange={setShowActivityBar}
            disabled>
            Activity Bar
          </DropdownMenuCheckboxItem>

          <DropdownMenuCheckboxItem
            checked={showPanel}
            onCheckedChange={setShowPanel}>
            Panel
          </DropdownMenuCheckboxItem>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenuWithToggleTrigger>
  );
}

/**
 * Radio group for exclusive choices
 */
export function DropdownMenuWithRadioGroup() {
  const [position, setPosition] = React.useState('bottom');

  return (
    <DropdownMenuWithToggleTrigger triggerLabel="Open">
      <DropdownMenuContent align="start" className={DROPDOWN_MENU_PANEL_CLASS}>
        <DropdownMenuGroup>
          <DropdownMenuLabel>Panel Position</DropdownMenuLabel>

          <DropdownMenuRadioGroup value={position} onValueChange={setPosition}>
            <DropdownMenuRadioItem value="top">Top</DropdownMenuRadioItem>
            <DropdownMenuRadioItem value="bottom">Bottom</DropdownMenuRadioItem>
            <DropdownMenuRadioItem value="right">Right</DropdownMenuRadioItem>
          </DropdownMenuRadioGroup>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenuWithToggleTrigger>
  );
}

/**
 * Destructive variant for irreversible actions
 */
export function DropdownMenuDestructive() {
  return (
    <DropdownMenuWithToggleTrigger triggerLabel="Actions">
      <DropdownMenuContent align="start" className={DROPDOWN_MENU_PANEL_CLASS}>
        <DropdownMenuGroup>
          <DropdownMenuItem>
            <Icon icon="edit" className="size-4" />
            Edit
          </DropdownMenuItem>

          <DropdownMenuItem>
            <Icon icon="send" className="size-4" />
            Share
          </DropdownMenuItem>
        </DropdownMenuGroup>

        <DropdownMenuSeparator />

        <DropdownMenuGroup>
          <DropdownMenuItem variant="destructive">
            <Icon icon="delete" className="size-4" />
            Delete
          </DropdownMenuItem>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenuWithToggleTrigger>
  );
}

// ============================================================================
// Example Metadata
// ============================================================================

export const examples = [
  {
    name: 'DropdownMenuDemo',
    title: 'Default',
    description: 'Basic dropdown menu with labels and separators.',
  },
  {
    name: 'DropdownMenuWithShortcuts',
    title: 'Shortcuts',
    description: 'Dropdown menu items with keyboard shortcut hints.',
  },
  {
    name: 'DropdownMenuWithIcons',
    title: 'With Icons',
    description: 'Dropdown items combined with icons for quick scanning.',
  },
  {
    name: 'DropdownMenuWithSubmenu',
    title: 'Submenu',
    description: 'Nested submenus for secondary actions.',
  },
  {
    name: 'DropdownMenuWithCheckboxes',
    title: 'Checkboxes',
    description: 'Checkbox items for toggling multiple options.',
  },
  {
    name: 'DropdownMenuWithRadioGroup',
    title: 'Radio Group',
    description: 'Radio group for exclusive choices.',
  },
  {
    name: 'DropdownMenuDestructive',
    title: 'Destructive',
    description: 'Destructive variant for irreversible actions.',
  },
];

// ============================================================================
// Legacy Format (for backwards compatibility)
// ============================================================================

export const dropdownMenu = {
  name: 'dropdown-menu',
  components: {
    Default: <DropdownMenuDemo />,
    Shortcuts: <DropdownMenuWithShortcuts />,
    'With Icons': <DropdownMenuWithIcons />,
    Submenu: <DropdownMenuWithSubmenu />,
    Checkboxes: <DropdownMenuWithCheckboxes />,
    'Radio Group': <DropdownMenuWithRadioGroup />,
    Destructive: <DropdownMenuDestructive />,
  },
};
